def operation(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")
    if n == 0:
        # If n=0, the last digit is 0, remaining is 0. 0 + 3*0 = 0.
        return 0

    d = n % 10  # Last digit
    n_prime = n // 10  # Remaining number
    n_new = n_prime + 3 * d
    return n_new

def test_sequence(start_n, steps):
    sequence = [start_n]
    current_n = start_n
    for i in range(steps):
        current_n = operation(current_n)
        sequence.append(current_n)
    return sequence

test_numbers = [10, 11, 20, 99, 123]
num_steps = 30

results = {}
for n in test_numbers:
    results[n] = test_sequence(n, num_steps)

for n, seq in results.items():
    print(f"--- Start N = {n} ---")
    print(seq)

